import { Boundary, signedArea, ellipseRing } from './line-growth-engine.js';
import { lineGrowthRegion } from './line-growth.js';
import { mulberry32 } from './helpers.js';
const num = (v,d,a,b) => Math.max(a,Math.min(b,Number.isFinite(+v)?+v:d));
const to = rings => rings.map(r=>r.map(([x,y])=>({x,y})));
const from = paths => paths.map(r=>r.map(q=>[q.x,q.y])).filter(r=>r.length>=3 && Math.abs(signedArea(r))>1e-6);
